javascript
// Test case 1: Invalid apiUrl with non-string type
console.log(getUrlForQuery(123, 'test')); // Expected output: null

// Test case 2: Empty userId string
console.log(getUrlForQuery('https://example.com/api/user', '')); // Expected output: null

// Test case 3: Valid inputs with special characters in userId
console.log(getUrlForQuery('https://example.com/api/user', 'user@123')); 
// Expected output: 'https://example.com/api/user/user@123'

